custom_qss:
/* ============================================================
   VERDANT - deep forest theme
   Design rules:
   - ONE gradient zone (main window + dialogs), flat everywhere else
   - no boxes: borders none, separation via accent underlines
   - docks/toolbars/menubar/statusbar transparent -> one continuous surface
   - rounded corners on interactive elements
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #d9efe2 !important;
}

/* --- the single gradient zone: big structural surfaces only --- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #0e1f16, stop:0.5 #091510, stop:1 #060d09) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #0e1f16, stop:0.5 #091510, stop:1 #060d09) !important;
}

/* --- menubar melts into the window --- */
QMenuBar {
    background: transparent !important;
}
QMenuBar::item {
    padding: 4px 10px;
    border-radius: 4px;
    background: transparent !important;
    color: #6b937f !important;
}
QMenuBar::item:selected {
    background: #16352a !important;
    color: #d9efe2 !important;
}

/* --- popups are the only place a hairline border is allowed --- */
QMenu {
    background: #0d1a14 !important;
    border: 1px solid #1c2f26;
    border-radius: 6px;
    padding: 6px;
}
QMenu::item {
    padding: 6px 24px 6px 16px;
    border-radius: 4px;
    background: transparent !important;
    color: #d9efe2 !important;
}
QMenu::item:selected {
    background: #16352a !important;
    color: #7ce8b8 !important;
}
QMenu::item:disabled {
    color: #41584c !important;
}
QMenu::separator {
    height: 1px;
    background: #1c2f26;
    margin: 5px 8px;
}

/* --- toolbars: transparent, icon buttons are not boxes --- */
QToolBar {
    background: transparent !important;
    spacing: 2px;
    padding: 3px;
}
QToolBar::separator {
    background: #1c2f26;
    width: 1px;
    margin: 5px 3px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 4px;
    color: #a8cdb9 !important;
}
QToolBar QToolButton:hover {
    background: #10221a !important;
    color: #d9efe2 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: #16352a !important;
    border-bottom: 2px solid #2fae6f;
    color: #7ce8b8 !important;
}
QToolBar QToolButton:disabled {
    color: #41584c !important;
}

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 4px;
    color: #a8cdb9 !important;
}
QToolButton:hover {
    background: #10221a !important;
    color: #d9efe2 !important;
}
QToolButton:checked, QToolButton:pressed {
    background: #16352a !important;
    border-bottom: 2px solid #2fae6f;
    color: #7ce8b8 !important;
}
QToolButton:disabled {
    color: #41584c !important;
}

/* --- buttons: flat raised surface, underline accent on checked --- */
QPushButton {
    background-color: #0f2019 !important;
    border-radius: 5px;
    padding: 5px 16px;
    color: #d9efe2 !important;
}
QPushButton:hover {
    background-color: #16352a !important;
    color: #7ce8b8 !important;
}
QPushButton:pressed {
    background-color: #1d4a35 !important;
}
QPushButton:checked {
    background-color: #123328 !important;
    border-bottom: 2px solid #2fae6f;
    color: #7ce8b8 !important;
}
QPushButton:disabled {
    background-color: #0a1611 !important;
    color: #41584c !important;
}

/* --- inputs: underline style, mint focus line, no box --- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: #0a1611 !important;
    border-bottom: 2px solid #1c2f26;
    border-radius: 4px 4px 0 0;
    padding: 4px 7px;
    color: #d9efe2 !important;
    selection-background-color: #16352a;
    selection-color: #7ce8b8;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-bottom: 2px solid #4ecf8e;
    background-color: #0c1d15 !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #41584c !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: #0a1611 !important;
    border-bottom: 2px solid #1c2f26;
    border-radius: 4px 4px 0 0;
    padding: 4px 7px;
    color: #d9efe2 !important;
}
QComboBox:hover {
    border-bottom: 2px solid #2fae6f;
}
QComboBox:focus {
    border-bottom: 2px solid #4ecf8e;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #0d1a14 !important;
    border: 1px solid #1c2f26;
    border-radius: 6px;
    padding: 4px;
    selection-background-color: #16352a;
}
QComboBox:disabled {
    color: #41584c !important;
}

/* --- checkboxes/radios: filled chips, no border rings --- */
QCheckBox, QRadioButton {
    color: #d9efe2 !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: #0f2019 !important;
    border-radius: 3px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: #16352a !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #2fae6f !important;
}
QCheckBox::indicator:checked:hover, QRadioButton::indicator:checked:hover {
    background: #4ecf8e !important;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #41584c !important;
}

/* --- tabs: selected gets a mint underline, no border boxes --- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #6b937f !important;
    padding: 6px 16px;
    border-radius: 4px 4px 0 0;
    margin: 0 1px;
}
QTabBar::tab:hover {
    color: #a8cdb9 !important;
    background: #0c1913 !important;
}
QTabBar::tab:selected {
    background: #0f2019 !important;
    color: #7ce8b8 !important;
    border-bottom: 2px solid #4ecf8e;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid #1c2f26;
    background: transparent !important;
}

/* --- docks: fully melted into the window, title = thin strip + accent tick --- */
QDockWidget {
    background: transparent !important;
    border: none;
}
QDockWidget::title {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid #1c2f26;
    border-left: 3px solid #2fae6f;
    padding: 6px 9px;
    color: #7ce8b8 !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #16352a !important;
}

/* --- group boxes: hairline divider underneath, title sits on the line --- */
QGroupBox {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid #1c2f26;
    margin-top: 12px;
    padding-top: 4px;
    font-weight: 600;
    color: #d9efe2 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #4ecf8e !important;
}

/* --- item views: soft content surfaces, rounded --- */
QAbstractItemView {
    background: #0a1611 !important;
    border: none;
    border-radius: 6px;
    alternate-background-color: #0c1913;
    selection-background-color: #123328;
    selection-color: #7ce8b8;
    outline: none;
}
QAbstractItemView::item {
    padding: 3px;
}
QAbstractItemView::item:hover {
    background: #0f2019 !important;
}
QAbstractItemView::item:selected {
    background: #123328 !important;
    color: #7ce8b8 !important;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView {
    background: transparent !important;
    border: none;
}
QHeaderView::section {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid #1c2f26;
    padding: 5px 7px;
    color: #6b937f !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    color: #a8cdb9 !important;
}

/* --- scrollbars: slim floating rounded handles --- */
QScrollBar:vertical {
    background: transparent !important;
    width: 11px;
    margin: 2px;
}
QScrollBar::handle:vertical {
    background: #16352a;
    border-radius: 4px;
    min-height: 28px;
}
QScrollBar::handle:vertical:hover {
    background: #2fae6f;
}
QScrollBar::handle:vertical:pressed {
    background: #4ecf8e;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal {
    background: transparent !important;
    height: 11px;
    margin: 2px;
}
QScrollBar::handle:horizontal {
    background: #16352a;
    border-radius: 4px;
    min-width: 28px;
}
QScrollBar::handle:horizontal:hover {
    background: #2fae6f;
}
QScrollBar::handle:horizontal:pressed {
    background: #4ecf8e;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner {
    background: transparent !important;
}

/* --- sliders: flat mint fill, round knob, no gradients --- */
QSlider::groove:horizontal {
    background: #0f2019 !important;
    height: 4px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: #2fae6f !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: #0f2019 !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #7ce8b8 !important;
    width: 12px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background: #4ecf8e !important;
}
QSlider::groove:vertical {
    background: #0f2019 !important;
    width: 4px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: #2fae6f !important;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background: #0f2019 !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #7ce8b8 !important;
    height: 12px;
    margin: 0 -5px;
    border-radius: 6px;
}
QSlider::handle:vertical:hover {
    background: #4ecf8e !important;
}

/* --- progress: one soft shine on the chunk only --- */
QProgressBar {
    background: #0a1611 !important;
    border-radius: 5px;
    text-align: center;
    color: #d9efe2 !important;
    min-height: 14px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2fae6f, stop:1 #4ecf8e) !important;
    border-radius: 5px;
}

/* --- statusbar melts, thin top hairline --- */
QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid #1c2f26;
    color: #6b937f !important;
}
QStatusBar::item {
    background: transparent !important;
}

/* --- tooltips: floating card with mint edge --- */
QToolTip {
    background: #0f2019 !important;
    border: 1px solid #2fae6f;
    border-radius: 4px;
    padding: 5px 8px;
    color: #d9efe2 !important;
}

/* --- splitters: invisible until hovered --- */
QSplitter {
    background: transparent !important;
    border: none;
}
QSplitter::handle {
    background: transparent !important;
}
QSplitter::handle:hover {
    background: #16352a !important;
}

/* --- everything else melts into the window gradient --- */
QAbstractScrollArea {
    background: transparent !important;
    border: none;
}
QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
}
